			hint = "Доставьте верховному друиду странный осколок.",
			text = [=[Осколок {link:emerald-dream}Изумрудного Сна{/link} пришел к нему от друида, который не желал о нем говорить. Хамуул всмотрелся в него, умолк и сказал только, что в Сне все обстоит не так, как думали друиды. Он посоветовал не говорить о таких вещах: это неразумно.]=],
