			text = [=[Мудрец Искатель Истины — один из мудрецов Громового Утеса, историков народа {link:tauren}таурен{/link}ов. Он собирает старые книги, реликвии и тайны со всего мира и изучает их ради своего народа. Верховному вождю он доверил бы свою жизнь. {link:forsaken}Отрекшимся{/link} он не доверяет.]=],
		},
		{
			title = "Значение",
			text = [=[Мудрец говорит за тех {link:tauren}таурен{/link}ов, которые сомневаются в договоре с мертвыми. Он верит, что {link:earthen-ring}Служители Земли{/link} желали добра, когда призывали Орду помочь им, но спрашивает себя, кто нашептывал на ухо их {link:shadow-council}Совет{/link}у старейшин. Он стоит и на пороге тайны поглубже — той, что уходит к создателям мира.]=],
		},
		{
			title = "Деяния",
			text = [=[• Он искал «Компендиум павших» у фанатиков {link:scarlet-monastery}Монастыря Алого ордена{/link}.
• Он изучает диски титана Норганнона, принесенные из {link:uldaman}Ульдаман{/link}а.
• Он и {link:nara-wildmane}Нара Буйногривая{/link} идут по следу дисков к {link:valley-of-the-watchers}Ульдум{/link}у.]=],
		},
	},
	chapters = {
		{
			title = "«Компендиум павших»",
			hint = [=[Принесите мудрецу книгу, которую стерегут фанатики Алого ордена.]=],
			text = [=[История Отрекшихся полна обмана, говорит мудрец, а договор был заключен слишком поспешно. Быть может, верховному вождю следовало прислушаться к предостережениям из {link:orgrimmar}Оргриммар{/link}а. Фанатики Алого ордена безумны, но они изучали нежить, и Искатель Истины хотел знать, что они узнали. Он уже начал сомневаться, существует ли их книга вообще.]=],
		},
		{
			title = "Платиновые диски",
			hint = "Принесите мудрецу реликвию из хранилищ Ульдамана.",
			text = [=[Из {link:uldaman}Ульдаман{/link}а пришла малая копия платиновых дисков титана Норганнона. Мудрец почуял в них тайны, которые земля веками крепко держала при себе. Он взялся выяснить, как они действуют, и пообещал, что со временем они раскроются.]=],
		},
		{
			title = "Знамения Ульдума",
			hint = "Идите по следу переведенных знаков с дисков.",
			text = [=[Знаки на дисках говорили о месте под названием {link:valley-of-the-watchers}Ульдум{/link}, которое большинство считает мифом. Искатель Истины рассказал об этом молодой друидке Наре Буйн{link:ogres}огр{/link}ивой, которая видела запечатанные врата в Долине Стражей в {link:tanaris}Танарисе{/link}. Вместе они решили, что диски и Ульдум связаны между собой.]=],
		},
	},
	mentions = {
		{ text = "Платиновые диски" },
		{ text = "Посмотреть, что будет" },
		{ text = "Задача на будущее" },
	},
	bonds = {
		{ id = "cairne-bloodhoof", name = "Кэрн Кровавое Копыто", note = "кому он доверил бы свою жизнь" },
		{ id = "nara-wildmane", name = "Нара Буйногривая", note = "разделяет его изучение Ульдума" },
		{ id = "magatha-grimtotem", name = "Магата Зловещий Тотем", note = "защитница договора, которому он не доверяет" },
	},
})

